const ELEMENT_PROP_KEYS = new Set(["theme","caption","brandIndex","stagger","thickness","accent","fontFamily","ink","background","scale","delay","grain","speed"]);

const ELEMENT_PROP_DEFAULTS: Record<string, unknown> = {
  theme: "dark",
  caption: "Connects to everything",
  brandIndex: 0,
  stagger: 2.2,
  thickness: 10,
  accent: "#3B5BFD",
  fontFamily: "Instrument Sans",
  scale: 1,
  delay: 0,
  grain: true,
  speed: 1,
};

type ChordRingElementProps = InteractiveBaseProps &
  InteractiveTransformProps &
  ComponentProps<typeof ChordRingBase>;

const ChordRingInner = forwardRef<
  HTMLDivElement,
  ChordRingElementProps & { readonly controls: SequenceControls | undefined }
>(({ controls, name, style, ...rest }, ref) => {
  const outlineRef = useRef<HTMLDivElement>(null);
  useImperativeHandle(ref, () => outlineRef.current as HTMLDivElement, []);
  const componentProps: Record<string, unknown> = { ...ELEMENT_PROP_DEFAULTS };
  const sequenceProps: Record<string, unknown> = {};
  for (const [key, value] of Object.entries(rest)) {
    if (ELEMENT_PROP_KEYS.has(key)) {
      if (value !== undefined) componentProps[key] = value;
    } else {
      sequenceProps[key] = value;
    }
  }
  return (
    <Sequence
      layout="none"
      {...sequenceProps}
      controls={controls}
      name={name ?? "<ChordRing>"}
      outlineRef={outlineRef}
    >
      <div
        ref={outlineRef}
        style={{
          position: "relative",
          width: "100%",
          height: "100%",
          display: "flex",
          alignItems: "center",
          justifyContent: "center",
          ...style,
        }}
      >
        <ChordRingBase
          {...(componentProps as unknown as ComponentProps<typeof ChordRingBase>)}
        />
      </div>
    </Sequence>
  );
});

export const ChordRing = Interactive.withSchema({
  Component: ChordRingInner,
  componentName: "<ChordRing>",
  componentIdentity: null,
  schema: elementSchema,
  supportsEffects: false,
});
